function validate(input) {
  const [{ drivers = [], trips = [] }] = input;
  const known = new Set(), names = new Set(), ids = new Set();
  let year = null;
  for (const [id, name] of drivers) {
    if (id === null || name === null) return 'driver_id and driver_name cannot be null.';
    if (known.has(id)) return `driver_id ${id} appears twice in drivers.`;
    known.add(id);
    const key = String(name).toLowerCase();
    if (names.has(key)) return `The name ${name} appears twice in drivers.`;
    names.add(key);
  }
  for (const [id, driver, day, distance, fuel] of trips) {
    if ([id, driver, day, distance, fuel].includes(null)) return 'No value in trips may be null.';
    if (ids.has(id)) return `trip_id ${id} appears twice in trips.`;
    ids.add(id);
    if (!known.has(driver)) return `driver_id ${driver} is not in drivers.`;
    if (!/^\d{4}-(0[1-9]|1[0-2])-\d{2}$/.test(day)) return `trip_date ${day} must look like 2023-01-31.`;
    if (year !== null && day.slice(0, 4) !== year) return 'All trips must fall in the same year.';
    year = day.slice(0, 4);
    if (!(distance > 0) || !(fuel > 0)) return 'distance_km and fuel_consumed must be positive.';
  }
  return null;
}

