function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const pick = list => list[int(list.length)];
  const pad = n => String(n).padStart(2, '0');
  const first = ['Alice', 'Bob', 'Carol', 'David', 'Emma', 'Frank', 'Grace', 'Henry', 'Ivy', 'Jack', 'Kara', 'Liam', 'Mia', 'Noah', 'Olga', 'Paul', 'Quinn', 'Rosa', 'Sam', 'Tara'];
  const last = ['Johnson', 'Smith', 'Davis', 'Wilson', 'Brown', 'Lee', 'Kim', 'Patel', 'Garcia', 'Chen', 'Novak', 'Silva', 'Moreau', 'Rossi', 'Haas', 'Berg', 'Ito', 'Okafor', 'Diaz', 'Young'];
  // Small pools make equal efficiencies (and so zero improvements) happen; the large pools add variety.
  const distances = small ? [100, 120.5, 150, 200] : [80, 95.5, 100, 120.5, 140, 150, 160, 180, 200, 250, 312.75];
  const fuels = small ? [8, 10, 12.5] : [6.4, 8, 9, 10, 11, 12.5, 15, 16.5, 22];
  const year = 2022 + int(3), shift = int(400);
  const count = small ? int(6) : 300, cap = small ? 8 : 2000;
  const drivers = [], rows = [];
  for (let id = 1; id <= count; id++) {
    const k = (shift + id) % 400;
    drivers.push([id, `${first[k % 20]} ${last[Math.floor(k / 20)]}`]);
    for (let n = int(small ? 4 : 8); n > 0; n--) {
      // June and July are drawn more often so the half-year boundary is exercised.
      const month = rand() < 0.3 ? 6 + int(2) : 1 + int(12);
      rows.push([id, `${year}-${pad(month)}-${pad(1 + int(30) % (month === 2 ? 28 : 30))}`, pick(distances), pick(fuels)]);
    }
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = int(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  const trips = rows.slice(0, cap).map((row, i) => [i + 1, ...row]);
  return [{ drivers, trips }];
}
